def resolve(path, cwd, links):
    # Count the number of symlinks followed
    link_count = [0]

    def resolve_helper(current_path, remaining_components):
        # Check if we've followed too many links
        if link_count[0] > 8:
            return None

        # If no remaining components, we're done
        if not remaining_components:
            return current_path if current_path else "/"

        # Get the next component
        component = remaining_components[0]
        rest = remaining_components[1:]

        # Skip empty components and '.'
        if component == "" or component == ".":
            return resolve_helper(current_path, rest)

        # Handle '..'
        if component == "..":
            if current_path == "/":
                # Already at root, stay at root
                return resolve_helper("/", rest)
            else:
                # Move to parent
                parent = current_path.rsplit("/", 1)[0]
                if not parent:
                    parent = "/"
                return resolve_helper(parent, rest)

        # Append the component to current path
        if current_path == "/":
            new_path = "/" + component
        else:
            new_path = current_path + "/" + component

        # Check if the new path is a symlink
        if new_path in links:
            link_count[0] += 1
            if link_count[0] > 8:
                return None

            target = links[new_path]

            # Resolve the target relative to the directory containing the link
            if target.startswith("/"):
                # Absolute target
                target_components = target.split("/")
            else:
                # Relative target - relative to directory containing the link
                link_dir = new_path.rsplit("/", 1)[0]
                if not link_dir:
                    link_dir = "/"
                # Parse the target relative to link_dir
                target_components = target.split("/")
                # We'll resolve starting from link_dir
                result = resolve_helper(link_dir, target_components)
                if result is None:
                    return None
                # Now continue with remaining components from the resolved target
                return resolve_helper(result, rest)

            # For absolute targets, start from root
            result = resolve_helper("", target_components)
            if result is None:
                return None
            # Continue with remaining components
            return resolve_helper(result, rest)

        # Not a symlink, continue with next component
        return resolve_helper(new_path, rest)

    # Normalize the input path
    if path.startswith("/"):
        # Absolute path
        components = path.split("/")
        # Remove empty strings from split (except the leading one which becomes "")
        components = [c for c in components if c]
        return resolve_helper("", components)
    else:
        # Relative path - relative to cwd
        components = path.split("/")
        components = [c for c in components if c]
        return resolve_helper(cwd, components)

